import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-revelacion-de-dios-ii', 'A',
 [dict(t=1659, e=1702, titulo='Hijos de la luz, sin temor', txt='Lo que les digo en la oscuridad, háblenlo en la luz. Usted diga conmigo: «Yo no soy hijo de tinieblas, yo soy hijo de la luz.» ¿Quién es la luz? Cristo. Y él te alumbra el camino. Por eso dice que, por muy torpe que seas, no vas a tropezar. Y dice: «Y lo que oís al oído, proclamadlo desde las azoteas.» No teman.'),
  dict(t=4144, e=4194, titulo='La roca es Cristo', txt='«Yo también te digo que tú eres Pedro, y sobre esta roca […]» No como dicen otros, que Pedro es la roca. La roca es Cristo. «[…] sobre esta roca edificaré mi iglesia. Y las puertas del Hades no prevalecerán contra ella.» Aleluya. Así que nosotros juntamente tenemos que salir, hermano, en victoria, para que el enemigo salga corriendo de este lugar.'),
  dict(t=4221, e=4266, titulo='Las llaves del Reino', txt='Mateo 16:19: «Yo te daré las llaves del reino de los cielos. Y lo que ates en la tierra será atado en los cielos, y lo que desates en la tierra será desatado en los cielos.» Viene algo glorioso para los que entiendan esta palabra, porque Dios te trae libertad. Te está entregando una llave hoy, en el nombre de Jesús. Ahora, qué tremendo. Mire, hermano, porque tenemos que aprender a desatar y atar.')],
 [dict(t=1706, txt='No teman, no tengan miedo, porque Dios los cubre. A usted no le puede pasar nada si Dios no lo permite.'),
  dict(t=3882, txt='No esté juzgando. El que los juzga es Dios.'),
  dict(t=4742, txt='Hoy tenemos que ponernos a cuentas con Dios, porque si cree como lleva su vida, va a morir engañado.')],
 ['«Yo no soy hijo de tinieblas, yo soy hijo de la luz.» ¿Hay algo que hoy te gustaría sacar a la luz delante de Dios en lugar de ocultarlo?',
  'Jesús dice que la roca sobre la que se edifica la iglesia es Cristo. ¿Sobre qué estás edificando tú tu vida esta semana?',
  'El predicador pide cerrar los ojos y pensar cómo estás llevando tu vida. ¿Qué te muestra Dios cuando le preguntas si lo estás agradando?'],
 inicio=999)
